-- Traceable opening balances for expanded production catalog
INSERT INTO inventory_movements (product_id, movement_type, quantity_in, quantity_out, balance_after, reference_type, reference_id, notes)
SELECT id, 'OPENING', current_stock, 0.000, current_stock, 'SYSTEM_SEED', 'INIT-PROD-2026', 'Opening store inventory balance for production catalog'
FROM products
WHERE id NOT IN (SELECT DISTINCT product_id FROM inventory_movements)
ON CONFLICT DO NOTHING;
